package com.alwaysontopkeybind;

import net.runelite.client.config.Config;
import net.runelite.client.config.ConfigGroup;
import net.runelite.client.config.ConfigItem;
import net.runelite.client.config.Keybind;
import net.runelite.client.config.Range;

@ConfigGroup("alwaysontopkeybind")
public interface AlwaysOnTopKeybindConfig extends Config
{
	@ConfigItem(
		keyName = "hotkey",
		name = "Toggle hotkey",
		description = "Pressing this toggles RuneLite's Always on top setting. Works while the RuneLite window is focused."
	)
	default Keybind hotkey()
	{
		return Keybind.NOT_SET;
	}

	@ConfigItem(
		keyName = "showOverlay",
		name = "On-screen notice",
		description = "Show Always On Top: On or Always On Top: Off at the top of the screen when you press the hotkey. Hold Alt to drag it."
	)
	default boolean showOverlay()
	{
		return true;
	}

	@Range(min = 1, max = 10)
	@ConfigItem(
		keyName = "overlaySeconds",
		name = "Notice seconds",
		description = "How many seconds the on-screen notice stays up."
	)
	default int overlaySeconds()
	{
		return 3;
	}

	@ConfigItem(
		keyName = "chatMessage",
		name = "Chat message",
		description = "Also show a game chat message saying whether Always on top is now on or off."
	)
	default boolean chatMessage()
	{
		return false;
	}
}

package com.alwaysontopkeybind;

import com.google.inject.Provides;
import javax.inject.Inject;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.config.RuneLiteConfig;
import net.runelite.client.input.KeyManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.HotkeyListener;

/**
 * Toggles RuneLite's own "Always on top" setting from a hotkey. It flips the same config value as the checkbox in
 * RuneLite's settings, so the window and the setting never disagree.
 */
@PluginDescriptor(
	name = "Always On Top Keybind",
	description = "Toggle RuneLite's Always on top setting with a hotkey and see an on-screen On/Off popup",
	tags = {"always on top", "hotkey", "keybind", "window"}
)
public class AlwaysOnTopKeybindPlugin extends Plugin
{
	private static final String ALWAYS_ON_TOP_KEY = "gameAlwaysOnTop";

	@Inject
	private Client client;

	@Inject
	private ClientThread clientThread;

	@Inject
	private KeyManager keyManager;

	@Inject
	private ConfigManager configManager;

	@Inject
	private RuneLiteConfig runeLiteConfig;

	@Inject
	private AlwaysOnTopKeybindConfig config;

	@Inject
	private OverlayManager overlayManager;

	@Inject
	private ToggleOverlay toggleOverlay;

	private final HotkeyListener hotkeyListener = new HotkeyListener(() -> config.hotkey())
	{
		@Override
		public void hotkeyPressed()
		{
			toggle();
		}
	};

	@Provides
	AlwaysOnTopKeybindConfig provideConfig(ConfigManager configManager)
	{
		return configManager.getConfig(AlwaysOnTopKeybindConfig.class);
	}

	@Override
	protected void startUp()
	{
		hotkeyListener.setEnabledOnLoginScreen(true);
		keyManager.registerKeyListener(hotkeyListener);
		overlayManager.add(toggleOverlay);
	}

	@Override
	protected void shutDown()
	{
		keyManager.unregisterKeyListener(hotkeyListener);
		overlayManager.remove(toggleOverlay);
	}

	private void toggle()
	{
		boolean enabled = !runeLiteConfig.gameAlwaysOnTop();
		configManager.setConfiguration(RuneLiteConfig.GROUP_NAME, ALWAYS_ON_TOP_KEY, enabled);
		toggleOverlay.show("Always On Top: " + (enabled ? "On" : "Off"), enabled);

		if (config.chatMessage())
		{
			clientThread.invokeLater(() ->
			{
				if (client.getGameState() == GameState.LOGGED_IN)
				{
					client.addChatMessage(ChatMessageType.GAMEMESSAGE, "",
						"Always on top: " + (enabled ? "on" : "off"), null);
				}
			});
		}
	}
}

package com.alwaysontopkeybind;

import java.awt.AlphaComposite;
import java.awt.Color;
import java.awt.Composite;
import java.awt.Dimension;
import java.awt.Graphics2D;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.KeyCode;
import net.runelite.client.ui.overlay.OverlayLayer;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.components.TitleComponent;

/**
 * A small text that appears for a few seconds saying whether Always on top was turned on or off.
 * Hold Alt to drag it; while Alt is held a sample shows so there is something to grab.
 */
class ToggleOverlay extends OverlayPanel
{
	private static final Color ON = new Color(0x5fe08a);
	private static final Color OFF = new Color(0xff6b6b);

	private final Client client;
	private final AlwaysOnTopKeybindConfig config;

	private static final long FADE_IN_MS = 180;
	private static final long FADE_OUT_MS = 450;

	private volatile String text;
	private volatile boolean on;
	private volatile long shownAt;
	private volatile long hideAt;

	@Inject
	private ToggleOverlay(Client client, AlwaysOnTopKeybindConfig config)
	{
		this.client = client;
		this.config = config;
		setPosition(OverlayPosition.TOP_CENTER);
		setLayer(OverlayLayer.ABOVE_WIDGETS);
	}

	void show(String message, boolean enabled)
	{
		long now = System.currentTimeMillis();
		// a popup that is already up just changes its text; it doesn't fade in all over again
		if (text == null || now >= hideAt)
		{
			shownAt = now;
		}
		text = message;
		on = enabled;
		hideAt = now + Math.max(config.overlaySeconds() * 1000L, FADE_IN_MS + FADE_OUT_MS);
	}

	/** 0 to 1: eases in over the first moments and out over the last. */
	private float opacity(long now)
	{
		float in = Math.min(1f, (now - shownAt) / (float) FADE_IN_MS);
		float out = Math.min(1f, (hideAt - now) / (float) FADE_OUT_MS);
		float t = Math.max(0f, Math.min(in, out));
		return t * t * (3f - 2f * t);
	}

	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (!config.showOverlay())
		{
			return null;
		}

		long now = System.currentTimeMillis();
		String shown = text;
		boolean live = shown != null && now < hideAt;
		boolean sample = !live && client.isKeyPressed(KeyCode.KC_ALT);
		if (!live && !sample)
		{
			return null;
		}

		panelComponent.getChildren().add(TitleComponent.builder()
			.text(sample ? "Always On Top (drag me)" : shown)
			.color(sample ? Color.WHITE : on ? ON : OFF)
			.build());

		Composite before = graphics.getComposite();
		graphics.setComposite(AlphaComposite.getInstance(AlphaComposite.SRC_OVER, sample ? 1f : opacity(now)));
		try
		{
			return super.render(graphics);
		}
		finally
		{
			graphics.setComposite(before);
		}
	}
}

package com.alwaysontopkeybind;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

/** Launches RuneLite with the plugin loaded, for development. */
public class AlwaysOnTopKeybindPluginTest
{
	public static void main(String[] args) throws Exception
	{
		ExternalPluginManager.loadBuiltin(AlwaysOnTopKeybindPlugin.class);
		RuneLite.main(args);
	}
}
